import { and, eq, isNull, notInArray } from \"drizzle-orm\";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from \"@/config/constants\";
import { emit } from \"@/lib/event-bus\";
import { newId } from \"@/lib/id\";
import { MilestoneStateError } from \"@/lib/milestones\";
import { assertCan } from \"@/lib/permissions\";
import { assertNotArchived } from \"@/lib/soft-delete\";
import { assertOrgScope } from \"@/lib/tenant\";
import { getDb, issues, milestones } from \"@/server/db\";
import * as projectRepo from \"@/server/repositories/project-repository\";
import { toIsoTimestamp } from \"@/types/common\";
import { actorEnvelope, NotFoundError, projectResource, requireFound } from \"./_support\";
import type { CloseMilestoneInput, CreateMilestoneInput, UpdateMilestoneInput } from \"@/schemas/milestone\";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from \"@/types/common\";
import type { Actor } from \"@/types/member\";
import type { Milestone, MilestoneWithProgress } from \"@/types/milestone\";

type Row = typeof milestones."'$inferSelect;
function mapMilestone(row: Row): Milestone {
  return { ...row, id: row.id as MilestoneId, orgId: row.orgId as OrgId, projectId: row.projectId as ProjectId,
    targetDate: row.targetDate as IsoTimestamp | null, closedAt: row.closedAt as IsoTimestamp | null,
    createdAt: row.createdAt as IsoTimestamp, updatedAt: row.updatedAt as IsoTimestamp };
}
function find(orgId: OrgId, id: MilestoneId): Milestone {
  const row = getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.id, id))).get();
  return mapMilestone(requireFound(row, "Milestone", id));
}
export function requireOpenMilestone(orgId: OrgId, projectId: ProjectId, id: MilestoneId): Milestone {
  const milestone = find(orgId, id);
  if (milestone.projectId !== projectId) throw new NotFoundError("Milestone", id);
  if (milestone.closedAt !== null) throw new MilestoneStateError("closed");
  return milestone;
}
async function projectFor(actor: Actor, orgId: OrgId, projectId: ProjectId, write: boolean) {
  const project = requireFound(await projectRepo.findProjectById(orgId, projectId), "Project", projectId);
  assertCan(actor, write ? "project:update" : "project:read", projectResource(project));
  if (write) assertNotArchived("Project", project.id, project);
  return project;
}
function siblings(orgId: OrgId, projectId: ProjectId): Row[] {
  return getDb().select().from(milestones).where(and(eq(milestones.orgId, orgId), eq(milestones.projectId, projectId))).all();
}
function checkName(rows: Row[], name: string, except?: MilestoneId) {
  const key = name.trim().toLowerCase();
  if (rows.some((row) => row.id !== except && row.name.trim().toLowerCase() === key)) throw new MilestoneStateError("name_taken");
}
function checkCap(rows: Row[]) {
  if (rows.filter((row) => row.closedAt === null).length >= MAX_OPEN_MILESTONES_PER_PROJECT) throw new MilestoneStateError("too_many_open");
}
export async function createMilestone(actor: Actor, input: CreateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await projectFor(actor, input.orgId, input.projectId, true);
  const db = getDb();
  const milestone = db.transaction(() => {
    const rows = siblings(input.orgId, input.projectId);
    checkName(rows, input.name); checkCap(rows);
    const now = toIsoTimestamp(new Date());
    return mapMilestone(db.insert(milestones).values({ id: newId(), orgId: input.orgId, projectId: input.projectId,
      name: input.name, targetDate: input.targetDate ?? null, closedAt: null, createdAt: now, updatedAt: now }).returning().get());
  });
  await emit("milestone.created", { ...actorEnvelope(actor), milestoneId: milestone.id, projectId: milestone.projectId });
  return milestone;
}
export async function updateMilestone(actor: Actor, input: UpdateMilestoneInput): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const before = find(input.orgId, input.milestoneId);
  await projectFor(actor, input.orgId, before.projectId, true);
  const db = getDb();
  return db.transaction(() => {
    if (input.name !== undefined) checkName(siblings(input.orgId, before.projectId), input.name, before.id);
    return mapMilestone(db.update(milestones).set({ ...(input.name !== undefined ? { name: input.name } : {}),
      ...(input.targetDate !== undefined ? { targetDate: input.targetDate } : {}), updatedAt: toIsoTimestamp(new Date()) })
      .where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, input.milestoneId))).returning().get());
  });
}
export async function closeMilestone(actor: Actor, input: CloseMilestoneInput): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const before = find(input.orgId, input.milestoneId);
  await projectFor(actor, input.orgId, before.projectId, true);
  const db = getDb();
  const target = input.moveOpenIssuesTo ?? null;
  const result = db.transaction(() => {
    const current = find(input.orgId, input.milestoneId);
    if (current.closedAt !== null) throw new MilestoneStateError("closed");
    if (target !== null) {
      if (target === current.id) throw new NotFoundError("Milestone", target);
      requireOpenMilestone(input.orgId, current.projectId, target);
    }
    const now = toIsoTimestamp(new Date());
    const moved = db.update(issues).set({ milestoneId: target, updatedAt: now }).where(and(
      eq(issues.orgId, input.orgId), eq(issues.projectId, current.projectId), eq(issues.milestoneId, current.id),
      isNull(issues.archivedAt), notInArray(issues.status, ["done", "canceled"]),
    )).returning({ id: issues.id }).all();
    const milestone = mapMilestone(db.update(milestones).set({ closedAt: now, updatedAt: now })
      .where(and(eq(milestones.orgId, input.orgId), eq(milestones.id, current.id))).returning().get());
    return { milestone, movedIssueIds: moved.map((row) => row.id as IssueId) };
  });
  await emit("milestone.closed", { ...actorEnvelope(actor), milestoneId: result.milestone.id, projectId: result.milestone.projectId,
    movedToMilestoneId: target, movedIssueIds: result.movedIssueIds });
  return result;
}
export async function reopenMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const before = find(orgId, milestoneId);
  await projectFor(actor, orgId, before.projectId, true);
  const db = getDb();
  const milestone = db.transaction(() => {
    const current = find(orgId, milestoneId);
    if (current.closedAt === null) throw new MilestoneStateError("already_open");
    checkCap(siblings(orgId, current.projectId));
    return mapMilestone(db.update(milestones).set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
      .where(and(eq(milestones.orgId, orgId), eq(milestones.id, milestoneId))).returning().get());
  });
  await emit("milestone.reopened", { ...actorEnvelope(actor), milestoneId, projectId: milestone.projectId });
  return milestone;
}
function withProgress(milestone: Milestone, now: number): MilestoneWithProgress {
  const rows = getDb().select({ status: issues.status }).from(issues).where(and(eq(issues.orgId, milestone.orgId),
    eq(issues.projectId, milestone.projectId), eq(issues.milestoneId, milestone.id), isNull(issues.archivedAt))).all();
  const closed = rows.filter((row) => row.status === "done" || row.status === "canceled").length;
  const progress = { total: rows.length, open: rows.length - closed, closed };
  return { milestone, progress, overdue: milestone.closedAt === null && milestone.targetDate !== null &&
    new Date(milestone.targetDate).getTime() < now && progress.open > 0 };
}
export async function listMilestones(actor: Actor, orgId: OrgId, projectId: ProjectId): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);
  await projectFor(actor, orgId, projectId, false);
  const now = Date.now();
  return siblings(orgId, projectId).map(mapMilestone).sort((a, b) =>
    Number(a.closedAt !== null) - Number(b.closedAt !== null) ||
    (a.targetDate === null ? (b.targetDate === null ? 0 : 1) : b.targetDate === null ? -1 : new Date(a.targetDate).getTime() - new Date(b.targetDate).getTime()) ||
    a.createdAt.localeCompare(b.createdAt)).map((milestone) => withProgress(milestone, now));
}
export async function getMilestone(actor: Actor, orgId: OrgId, milestoneId: MilestoneId): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);
  const milestone = find(orgId, milestoneId);
  await projectFor(actor, orgId, milestone.projectId, false);
  return withProgress(milestone, Date.now());
}
EOF'

